ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
	message: {
		subject: "RX Processing Failed After Maximum Retries",
		body: {
			contentType: "HTML",
			content: "<html><body>" ++
        "<p>Hi Team,</p>" ++
        "<p>The RX record processing has failed after exceeding the configured retry limit due to a connection issue.</p>" ++
        "<p><strong>Processing Details:</strong></p>" ++
        "<ul>" ++
          "<li><strong>Process:</strong> RX Record Processing</li>" ++
          "<li><strong>Status:</strong> Failed after maximum retry attempts</li>" ++
          "<li><strong>Reason:</strong> Connection issue</li>" ++
          "<li><strong>Retry Status:</strong> Maximum retries exhausted</li>" ++
          "<li><strong>MQ Status:</strong> Message successfully published to MQ for reprocessing</li>" ++
        "</ul>" ++
        "<p>The message has been successfully published to MQ and will be available for subsequent processing.</p>" ++
        "<p>Please investigate the underlying connection issue.</p>" ++
        "<p>Thanks.</p>" ++
        "</body></html>"
		},
		toRecipients: [{
			emailAddress: {
				address: p('outlook.toRecipients')
			}
		}]
	},
	saveToSentItems: true
}
